    // Simple Shelf Bin Packing Algorithm
    function packImages() {
      if (loadedImages.length === 0) return alert('Загрузите картинки!');

      const padding = parseInt(paddingInput.value);
      const maxSize = parseInt(maxSizeInput.value);

      // Sort images by height (largest first)
      const rects = [...loadedImages].sort((a, b) => b.h - a.h);

      let currentX = 0;
      let currentY = 0;
      let maxRowHeight = 0;
      let canvasW = 0;
      let canvasH = 0;

      const packed = [];

      for (const rect of rects) {
        if (currentX + rect.w + padding > maxSize) {
          currentY += maxRowHeight + padding;
          currentX = 0;
          maxRowHeight = 0;
        }

        if (currentY + rect.h + padding > maxSize) {
          alert('Некоторые картинки не влезли в атлас! Увеличьте макс. размер.');
          break;
        }

        packed.push({
          name: rect.name,
          img: rect.img,
          x: currentX,
          y: currentY,
          w: rect.w,
          h: rect.h
        });

        currentX += rect.w + padding;
        maxRowHeight = Math.max(maxRowHeight, rect.h);

        canvasW = Math.max(canvasW, currentX);
        canvasH = Math.max(canvasH, currentY + maxRowHeight);
      }

      // Power of Two rounding
      const potW = Math.pow(2, Math.ceil(Math.log2(canvasW)));
      const potH = Math.pow(2, Math.ceil(Math.log2(canvasH)));

      atlasCanvas.width = potW;
      atlasCanvas.height = potH;

      ctx.clearRect(0, 0, potW, potH);

      const jsonFrames = {};

      for (const item of packed) {
        ctx.drawImage(item.img, item.x, item.y, item.w, item.h);

        jsonFrames[item.name] = {
          frame: { x: item.x, y: item.y, w: item.w, h: item.h },
          rotated: false,
          trimmed: false,
          spriteSourceSize: { x: 0, y: 0, w: item.w, h: item.h },
          sourceSize: { w: item.w, h: item.h }
        };
      }

      packedData = {
        frames: jsonFrames,
        meta: {
          app: "xGR3ENx Texture Packer",
          image: "atlas.png",
          format: "RGBA8888",
          size: { w: potW, h: potH },
          scale: "1"
        }
      };

      exportGroup.style.display = 'flex';
    }

