      loadedFiles.forEach(file => {
        totalDuration += file.duration + gap;
      });

      // Render offline
      const sampleRate = audioContext.sampleRate;
      const offlineCtx = new OfflineAudioContext(2, sampleRate * totalDuration, sampleRate);

      let currentTime = 0;
      spriteJson = { resources: [] };

      loadedFiles.forEach(file => {
        const source = offlineCtx.createBufferSource();
        source.buffer = file.buffer;
        source.connect(offlineCtx.destination);
        source.start(currentTime);

        spriteJson.resources.push({
          name: file.name,
          start: parseFloat(currentTime.toFixed(3)),
          end: parseFloat((currentTime + file.duration).toFixed(3)),
          duration: parseFloat(file.duration.toFixed(3))
        });

        currentTime += file.duration + gap;
      });

      try {
        const renderedBuffer = await offlineCtx.startRendering();
