    function processImage() {
      if (!currentImgObj) return;

      const canvas = document.createElement('canvas');
      let width = currentImgObj.width;
      let height = currentImgObj.height;

      const maxW = parseInt(maxWidthInput.value);
      if (maxW && width > maxW) {
        height = Math.round(height * (maxW / width));
        width = maxW;
      }

      canvas.width = width;
      canvas.height = height;
      const ctx = canvas.getContext('2d');

      // If jpeg, fill white background to avoid transparent->black issue
      const format = formatSelect.value;
      if (format === 'image/jpeg') {
        ctx.fillStyle = '#FFFFFF';
        ctx.fillRect(0, 0, width, height);
      }

      ctx.drawImage(currentImgObj, 0, 0, width, height);

      const quality = parseInt(qualitySlider.value) / 100;
      const dataUrl = canvas.toDataURL(format, quality);

      document.getElementById('optPlaceholder').style.display = 'none';
      optImg.style.display = 'block';
      optImg.src = dataUrl;

      // Calc size roughly
      const base64str = dataUrl.split(',')[1];
      const sizeBytes = atob(base64str).length;
      optSize.textContent = (sizeBytes / 1024).toFixed(1) + ' KB';

      const diff = currentFile.size - sizeBytes;
      if (diff > 0) {
        const percent = ((diff / currentFile.size) * 100).toFixed(0);
        savingBadge.textContent = `-${percent}%`;
        savingBadge.style.display = 'block';
