      const code = inputCode.value;
      if (!code.trim()) return;

      try {
        if (typeof Terser === 'undefined') {
          throw new Error('Terser library failed to load.');
        }

        outputCode.value = "Сжатие...";

        // Terser is loaded globally from CDN
        const result = await Terser.minify(code, {
          compress: true,
          mangle: true
        });

        if (result.error) {
          throw result.error;
        }

        outputCode.value = result.code;
        showStats(code, result.code);
        copyBtn.style.display = 'inline-block';

      } catch (e) {
        logError(e.message || e);
        outputCode.value = "";
      }
    });

    minifyCssBtn.addEventListener('click', () => {
      errorLog.style.display = 'none';
      let code = inputCode.value;
      if (!code.trim()) return;

      try {
        // Basic CSS minification (regex)
        code = code.replace(/\/\*[\s\S]*?\*\//g, ''); // remove comments
        code = code.replace(/\s+/g, ' '); // collapse whitespace
        code = code.replace(/\s*([\{\}\:\;\,])\s*/g, '$1'); // remove space around separators
        code = code.replace(/;\}/g, '}'); // remove trailing semicolon

        outputCode.value = code;
        showStats(inputCode.value, code);
        copyBtn.style.display = 'inline-block';
      } catch (e) {
        logError(e.message || e);
      }
    });

    copyBtn.addEventListener('click', () => {
      outputCode.select();
      document.execCommand('copy');
      copyBtn.textContent = 'Скопировано!';
      setTimeout(() => copyBtn.textContent = 'Скопировать', 2000);
    });

const networks = {
