    const networkSelect = document.getElementById('networkSelect');
    const networkReqs = document.getElementById('networkReqs');
    const dropzone = document.getElementById('dropzone');
    const fileInput = document.getElementById('fileInput');
    const logBox = document.getElementById('logBox');

    function updateReqs() {
      const net = networks[networkSelect.value];
      let html = `<li>Макс размер: ${net.maxSize / 1024 / 1024} MB</li>`;
      html += `<li>Архив/Файл: ${net.singleFile ? 'Только 1 файл (index.html)' : 'ZIP архив (index.html в корне)'}</li>`;
      html += `<li>Ассеты: Встроены (Base64)</li>`;
      if (net.mraid) html += `<li>MRAID: Требуется mraid.js</li>`;
      if (net.clickDesc !== 'none') html += `<li>Клик URL: ${net.clickDesc}</li>`;
      networkReqs.innerHTML = html;
    }

    networkSelect.addEventListener('change', updateReqs);
    updateReqs();

    function log(msg, type = 'info', details = null) {
      const icons = { info: '>', success: '✓', warn: '⚠', error: '✕' };
      const div = document.createElement('div');
      div.className = `log-entry log-${type}`;
      if (details) {
        div.classList.add('clickable');
        div.onclick = () => {
          let severity = '';
          let titleColor = '#fff';
          if (type === 'error') {
            severity = 'СТАТУС: КРИТИЧЕСКАЯ ОШИБКА (Креатив будет отклонен площадкой)\n\n';
            titleColor = '#ff3333';
          } else if (type === 'warn') {
            severity = 'СТАТУС: ПРЕДУПРЕЖДЕНИЕ (Некритично, но возможны проблемы с отображением/трекингом)\n\n';
            titleColor = '#ffcc00';
          }

          document.getElementById('errorModalTitle').textContent = type === 'error' ? 'ДЕТАЛИ ОШИБКИ' : 'ДЕТАЛИ ПРЕДУПРЕЖДЕНИЯ';
          document.getElementById('errorModalTitle').style.color = titleColor;
          document.getElementById('errorModalText').textContent = severity + details;
          document.getElementById('errorModal').style.display = 'flex';
        };
      }
      div.innerHTML = `<span class="log-icon">${icons[type] || '>'}</span><span class="log-text">${msg}</span>`;
      logBox.appendChild(div);
      logBox.scrollTop = logBox.scrollHeight;
    }

    function clearLog() {
      logBox.innerHTML = '';
    }

    dropzone.addEventListener('click', () => fileInput.click());
    dropzone.addEventListener('dragover', (e) => { e.preventDefault(); dropzone.classList.add('dragover'); });
    dropzone.addEventListener('dragleave', () => dropzone.classList.remove('dragover'));
    dropzone.addEventListener('drop', (e) => {
      e.preventDefault();
      dropzone.classList.remove('dragover');
      if (e.dataTransfer.files.length) handleFile(e.dataTransfer.files[0]);
    });
    fileInput.addEventListener('change', (e) => {
      if (e.target.files.length) handleFile(e.target.files[0]);
    });

    async function handleFile(file) {
      clearLog();
      log(`Анализ файла: ${file.name} (${(file.size / 1024).toFixed(2)} KB)`, 'info');
      const net = networks[networkSelect.value];

      if (file.size > net.maxSize) {
        log(`ОШИБКА: Размер файла превышает лимит ${net.maxSize / 1024 / 1024} MB`, 'error', `Ваш файл весит ${(file.size / 1024 / 1024).toFixed(2)} MB, что превышает ограничение площадки.\n\nПопробуйте сжать изображения (используйте TinyPNG или TexturePacker), минифицировать JS/CSS или уменьшить качество аудио.`);
        return;
      } else {
        log(`Размер файла в норме (Лимит: ${net.maxSize / 1024 / 1024} MB)`, 'success');
      }

      if (file.name.endsWith('.zip')) {
        if (net.singleFile) {
          log(`ПРЕДУПРЕЖДЕНИЕ: Сеть ${net.name} предпочитает один HTML файл, а не ZIP.`, 'warn', `Сеть поддерживает загрузку одного HTML файла, где все ресурсы внедрены внутрь (Base64).\n\nВы загрузили ZIP архив. Убедитесь, что площадка поддерживает архивы в вашем случае.`);
        }
        await validateZip(file, net);
      } else if (file.name.endsWith('.html')) {
        await validateHtmlFile(file, net);
      } else {
        log(`ОШИБКА: Неподдерживаемый формат файла. Загрузите ZIP или HTML.`, 'error');
      }
    }

    let currentPlayableHtml = '';
    const previewContainer = document.getElementById('previewContainer');
    const previewIframe = document.getElementById('previewIframe');
    const deviceMock = document.getElementById('deviceMock');
    const deviceSelect = document.getElementById('deviceSelect');
    const btnOrientation = document.getElementById('btnOrientation');
    const btnReload = document.getElementById('btnReload');
    let isLandscape = false;

    let isMuted = false;
    const btnMute = document.getElementById('btnMute');

    deviceSelect.addEventListener('change', updateDeviceSize);
    btnOrientation.addEventListener('click', () => {
      isLandscape = !isLandscape;
      btnOrientation.innerHTML = isLandscape ? 
        `<svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><rect x="2" y="5" width="20" height="14" rx="2" ry="2"></rect></svg><span>Portrait</span>` :
        `<svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><rect x="5" y="2" width="14" height="20" rx="2" ry="2"></rect></svg><span>Landscape</span>`;
      updateDeviceSize();
    });

    btnMute.addEventListener('click', () => {
      isMuted = !isMuted;
      btnMute.innerHTML = isMuted ? 
        `<svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="#ff3333" stroke-width="2"><polygon points="11 5 6 9 2 9 2 15 6 15 11 19 11 5"></polygon><line x1="23" y1="9" x2="17" y2="15"></line><line x1="17" y1="9" x2="23" y2="15"></line></svg>` : 
        `<svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><polygon points="11 5 6 9 2 9 2 15 6 15 11 19 11 5"></polygon><path d="M15.54 8.46a5 5 0 0 1 0 7.07"></path></svg>`;
    });

    btnReload.addEventListener('click', () => {
      if (currentPlayableHtml) previewPlayable(currentPlayableHtml);
    });

    function updateDeviceSize() {
      const dims = deviceSelect.value.split('x');
      let w = parseInt(dims[0]);
      let h = parseInt(dims[1]);
      const notch = document.getElementById('deviceNotch');

      if (isLandscape) {
        [w, h] = [h, w]; // Swap
        notch.style.display = 'none';
      } else {
        notch.style.display = 'block';
      }

      // Scale down if it's a huge device like iPad to fit the screen
      const maxW = 800;
      if (w > maxW) {
        const ratio = maxW / w;
        w = maxW;
        h = h * ratio;
      }
      deviceMock.style.width = w + 'px';
      deviceMock.style.height = h + 'px';
    }

    function previewPlayable(html) {
      currentPlayableHtml = html;
      previewContainer.style.display = 'flex';

      const interceptor = `<script>
        (function() {
          const originalError = console.error;
          const originalWarn = console.warn;
          console.error = function(...args) {
            window.parent.postMessage({type: 'console', level: 'error', args: args.map(a => String(a))}, '*');
            originalError.apply(console, args);
          };
          console.warn = function(...args) {
            window.parent.postMessage({type: 'console', level: 'warn', args: args.map(a => String(a))}, '*');
            originalWarn.apply(console, args);
          };
          window.onerror = function(msg, url, line) {
            window.parent.postMessage({type: 'console', level: 'error', args: [msg + ' (line ' + line + ')']}, '*');
          };
        })();
      <\/script>`;

      const injectHtml = html.replace('<head>', '<head>' + interceptor);
      previewIframe.srcdoc = injectHtml;
      updateDeviceSize();
      // Scroll to preview
      setTimeout(() => previewContainer.scrollIntoView({ behavior: 'smooth', block: 'start' }), 500);
    }

    window.addEventListener('message', (event) => {
      if (event.data && event.data.type === 'console') {
        const level = event.data.level;
        const msg = event.data.args.join(' ');
        log(`[ПРЕВЬЮ] ${msg}`, level === 'error' ? 'error' : 'warn');
      }
    });

    async function validateZip(file, net) {
      try {
        const zip = await JSZip.loadAsync(file);
        let hasIndex = false;
        let fileCount = 0;
        let indexHtml = "";

        for (let [filename, zipEntry] of Object.entries(zip.files)) {
          if (!zipEntry.dir) fileCount++;
          if (filename === 'index.html') {
            hasIndex = true;
            indexHtml = await zipEntry.async("string");
            validateHtmlContent(indexHtml, net);
          }
        }

        if (!hasIndex) {
          log('ОШИБКА: index.html не найден в корне архива!', 'error', 'Архив не содержит файл index.html в корневой директории.\n\nЧастая ошибка: вы запаковали папку с проектом, а не сами файлы. Выделите все файлы внутри папки (включая index.html) и создайте ZIP архив из них.');
        } else {
          log('index.html найден в корне архива.', 'success');
          previewPlayable(indexHtml);
        }

        if (net.singleFile && fileCount > 1) {
          log(`ОШИБКА: Сеть ${net.name} требует сборку в 1 файл (Single File). В архиве ${fileCount} файлов.`, 'error', `Эта рекламная сеть принимает только ОДИН файл index.html.\n\nВам необходимо использовать инструмент "Playable Inliner" на нашем сайте, чтобы внедрить все ваши изображения, скрипты и стили прямо внутрь HTML файла (в виде Base64-строк).`);
        } else {
          log(`Количество файлов в архиве: ${fileCount}`, 'info');
        }

        log('Проверка ZIP архива завершена.', 'info');
      } catch (e) {
        log(`ОШИБКА чтения ZIP: ${e.message}`, 'error');
      }
    }

    async function validateHtmlFile(file, net) {
      const text = await file.text();
      validateHtmlContent(text, net);
      previewPlayable(text);
      log('Проверка HTML файла завершена.', 'info');
    }

    function validateHtmlContent(html, net) {
      log('Анализ содержимого HTML...', 'info');

      // Check MRAID
      if (net.mraid) {
        if (html.includes('mraid.js')) {
          log('mraid.js найден (ожидается для данной сети).', 'success');
        } else {
          log(`ОШИБКА: ${net.name} требует mraid.js, но он не найден в HTML.`, 'error', `Рекламная сеть ${net.name} требует наличие скрипта MRAID для отслеживания показов и кликов.\n\nВам необходимо добавить тег:\n<script src="mraid.js"><` + `/script>\n\nВнутрь тега <head> вашего index.html файла.`);
        }
      }

      // Check Custom Click
      if (net.customClick !== 'none') {
        const searchTerms = net.customClick;
        if (html.includes(searchTerms)) {
          log(`Скрипт клика найден: ${net.clickDesc}`, 'success');
        } else {
          log(`ПРЕДУПРЕЖДЕНИЕ: Не найден вызов ${net.clickDesc}. Убедитесь, что логика клика реализована верно.`, 'warn', `Сеть требует специфичный вызов для обработки клика (CTA).\n\nОжидаемый вызов: ${net.clickDesc}\n\nУбедитесь, что он вызывается при нажатии на кнопку "Скачать/Играть".`);
        }
      }

      // Check external resources
      const externalLinkRegex = /(?:src|href)=["'](http|https):\/\/[^"']+["']/gi;
      const externalsRaw = [...html.matchAll(externalLinkRegex)];

      // Filter out allowed external links based on network
      let allowedExternals = [];
      if (net.name === 'Google Ads (UAC)') {
        allowedExternals.push('tpc.googlesyndication.com');
      }

      const externals = externalsRaw.filter(match => {
        const url = match[0];
        for (let allowed of allowedExternals) {
          if (url.includes(allowed)) return false;
        }
        return true;
      });

      if (externals.length > 0) {
        const foundUrls = externals.map(m => m[0]).join('\n');
        log(`ОШИБКА: Обнаружены внешние ссылки! Найдено: ${externals.length}`, 'error', `Playable Ads должны работать полностью оффлайн (ассеты заинлайнены).\n\nНайден следующий код с внешними ссылками:\n\n${foundUrls}\n\nКонвертируйте картинки/аудио в Base64, а внешние скрипты и стили скопируйте внутрь HTML. (Используйте наш Playable Inliner)`);
      } else {
        log('Внешних загрузок сторонних ресурсов не обнаружено.', 'success');
      }

      // Check relative links (only relevant for single file networks)
      const relativeRegex = /(?:src|href)=["'](?!http|https|data:|mraid\.js|dapi\.js|#|javascript:)([^"']+)["']/gi;
      const relatives = [...html.matchAll(relativeRegex)];
      if (relatives.length > 0 && net.singleFile) {
        // limit to first 10 to avoid massive modal
        const foundRels = relatives.slice(0, 10).map(m => m[0]).join('\n') + (relatives.length > 10 ? '\n...и еще ' + (relatives.length - 10) + ' файлов.' : '');
        log(`ОШИБКА: Найдены относительные пути (${relatives.length}), хотя сеть требует один файл.`, 'error', `Сеть ${net.name} принимает только один HTML файл.\nОднако в вашем коде найдены ссылки на локальные файлы (которые потеряются при загрузке):\n\n${foundRels}\n\nЗаинлайньте все ассеты в HTML (используйте наш Playable Inliner).`);
      }

      // Check Google Ads specific requirements
      if (net.name === 'Google Ads (UAC)') {
        // Check exitapi
        if (html.includes('exitapi.js')) {
          log('Скрипт exitapi.js найден.', 'success');
        } else {
          log('ОШИБКА: Google Ads требует скрипт exitapi.js', 'error', `Для Google Ads (UAC) обязательно подключение API выходов.\n\nДобавьте в <head>:\n<script src="https://tpc.googlesyndication.com/pagead/gadgets/html5/api/exitapi.js"><` + `/script>`);
        }

        // Check ad.size
        if (html.includes('ad.size')) {
          log('Метатег ad.size найден.', 'success');
        } else {
          log('ПРЕДУПРЕЖДЕНИЕ: Google Ads требует метатег ad.size (например, <meta name="ad.size" content="width=320,height=480">).', 'warn', `Для Google Ads (UAC) обязательно наличие метатега с размерами креатива.\n\nДобавьте в <head>:\n<meta name="ad.size" content="width=320,height=480">`);
        }
      } // <-- MISSING BRACE FIXED

      // Check Mintegral specific requirements
      if (net.name === 'Mintegral') {
        if (!html.includes('window.gameReady')) {
          log('ПРЕДУПРЕЖДЕНИЕ: Mintegral рекомендует использовать window.gameReady()', 'warn', `Сеть Mintegral использует коллбеки для контроля отображения креста закрытия.\n\nРекомендуется вызывать:\nwindow.gameReady && window.gameReady();\n\nСразу после полной инициализации игры.`);
        }
        if (!html.includes('window.gameEnd')) {
          log('ПРЕДУПРЕЖДЕНИЕ: Mintegral рекомендует использовать window.gameEnd()', 'warn', `Сеть Mintegral использует коллбек для понимания, когда игра завершена (победа или проигрыш).\n\nВызовите:\nwindow.gameEnd && window.gameEnd();\nв конце геймплея.`);
        }
      }
    }

