      swirl: { count: 10, speed: 5, spread: 360, gravity: 0, life: 90, size: 3, colors: ['#aa00ff', '#0000ff'], fade: true, shape: 'ring' }
    };

    let activeParams = {};
    let particles = [];
    let isDrawing = false;
    let mouseX = 0, mouseY = 0;

    const canvas = document.getElementById('renderCanvas');
    const ctx = canvas.getContext('2d');
    const presetSelect = document.getElementById('presetSelect');
    const controlsContainer = document.getElementById('controlsContainer');
    const btnExport = document.getElementById('btnExport');

    function resizeCanvas() {
        const rect = canvas.parentElement.getBoundingClientRect();
        canvas.width = rect.width;
        canvas.height = rect.height || 400;
    }
    window.addEventListener('resize', resizeCanvas);
    resizeCanvas();

    function buildUI(presetKey) {
        const p = presets[presetKey];
        activeParams = JSON.parse(JSON.stringify(p)); // deep copy

        controlsContainer.innerHTML = '';

        const config = [
            { id: 'count', label: 'Частиц за кадр (Count)', min: 1, max: 100, step: 1 },
            { id: 'speed', label: 'Скорость (Speed)', min: 0.1, max: 20, step: 0.1 },
            { id: 'spread', label: 'Разброс угла (Spread)', min: 0, max: 360, step: 1 },
            { id: 'gravity', label: 'Гравитация (Gravity)', min: -0.5, max: 0.5, step: 0.01 },
            { id: 'life', label: 'Время жизни (Life)', min: 10, max: 500, step: 1 },
            { id: 'size', label: 'Размер (Size)', min: 1, max: 100, step: 1 }
        ];

        config.forEach(c => {
            const group = document.createElement('div');
            group.className = 'form-group';
            group.innerHTML = `
                <label class="form-label">${c.label}: <span id="val_${c.id}">${activeParams[c.id]}</span></label>
                <input type="range" id="input_${c.id}" min="${c.min}" max="${c.max}" step="${c.step}" value="${activeParams[c.id]}">
            `;
            controlsContainer.appendChild(group);

            const input = group.querySelector(`#input_${c.id}`);
            input.addEventListener('input', (e) => {
                const val = parseFloat(e.target.value);
                group.querySelector(`#val_${c.id}`).innerText = val;
                activeParams[c.id] = val;
            });
        });

        // Shape select
        const shapeGroup = document.createElement('div');
        shapeGroup.className = 'form-group';
        shapeGroup.innerHTML = `
            <label class="form-label">Форма (Shape)</label>
            <select id="input_shape" class="form-select">
                <option value="circle">Круг (Circle)</option>
                <option value="square">Квадрат (Square)</option>
                <option value="star">Звезда (Star)</option>
                <option value="line">Линия (Line)</option>
                <option value="ring">Кольцо (Ring)</option>
                <option value="heart">Сердце (Heart)</option>
            </select>
        `;
        controlsContainer.appendChild(shapeGroup);
        const shapeSelect = shapeGroup.querySelector('#input_shape');
        shapeSelect.value = activeParams.shape;
        shapeSelect.addEventListener('change', e => activeParams.shape = e.target.value);

        // Colors
        const colorGroup = document.createElement('div');
        colorGroup.className = 'form-group';
        let colorHtml = `<label class="form-label">Цвета (Палитра)</label><div class="color-inputs">`;
        for(let i=0; i<4; i++) {
            const col = activeParams.colors[i] || '#000000';
            colorHtml += `<input type="color" id="color_${i}" value="${col}" ${i >= activeParams.colors.length ? 'style="display:none;"' : ''}>`;
        }
        colorHtml += `</div>`;
        colorGroup.innerHTML = colorHtml;
        controlsContainer.appendChild(colorGroup);

        for(let i=0; i<4; i++) {
            const input = colorGroup.querySelector(`#color_${i}`);
            if(input) {
                input.addEventListener('input', (e) => {
                    activeParams.colors[i] = e.target.value;
                });
            }
        }
    }

    presetSelect.addEventListener('change', e => {
        buildUI(e.target.value);
        document.getElementById('codeExportArea').style.display = 'none';
        particles = [];
    });

    document.getElementById('btnSavePreset').addEventListener('click', () => {
      const pKey = presetSelect.value;
      const valuesToSave = {};
      Object.keys(presets[pKey].config).forEach(k => {
        valuesToSave[k] = presets[pKey].config[k].value;
      });
      localStorage.setItem('particle_preset_' + pKey, JSON.stringify(valuesToSave));
      alert('Настройки для ' + pKey + ' сохранены!');
    });

    document.getElementById('btnLoadPreset').addEventListener('click', () => {
      const pKey = presetSelect.value;
      const saved = localStorage.getItem('particle_preset_' + pKey);
      if (saved) {
        const values = JSON.parse(saved);
        Object.keys(values).forEach(k => {
          if (presets[pKey].config[k]) {
            presets[pKey].config[k].value = values[k];
          }
        });
        buildUI(pKey);
        particles = [];
        alert('Настройки для ' + pKey + ' загружены!');
      } else {
        alert('Нет сохраненных настроек для этого эффекта.');
      }
    });

    // Mouse interaction
    canvas.addEventListener('mousedown', (e) => {
        isDrawing = true;
        emitAtMouse(e);
    });
    canvas.addEventListener('mousemove', (e) => {
        if(isDrawing) emitAtMouse(e);
    });
    canvas.addEventListener('mouseup', () => isDrawing = false);
    canvas.addEventListener('mouseleave', () => isDrawing = false);

    function emitAtMouse(e) {
        const rect = canvas.getBoundingClientRect();
        mouseX = e.clientX - rect.left;
        mouseY = e.clientY - rect.top;

        // Determine emit direction based on preset
        let baseAngle = -Math.PI / 2; // Upwards usually
        if (activeParams.shape === 'line' && activeParams.spread < 45) {
            baseAngle = Math.PI / 2; // rain falls down
        }

        for (let i = 0; i < activeParams.count; i++) {
            const spreadRad = (activeParams.spread * Math.PI) / 180;
            const angle = baseAngle + (Math.random() - 0.5) * spreadRad;
            const speed = activeParams.speed * (0.5 + Math.random() * 0.5);

            particles.push({
                x: mouseX,
                y: mouseY,
                vx: Math.cos(angle) * speed,
                vy: Math.sin(angle) * speed,
                life: activeParams.life * (0.5 + Math.random() * 0.5),
                maxLife: activeParams.life,
                size: activeParams.size * (0.5 + Math.random() * 0.5),
                color: activeParams.colors[Math.floor(Math.random() * activeParams.colors.length)],
                shape: activeParams.shape,
                gravity: activeParams.gravity
            });
        }
    }

    function render() {
        ctx.fillStyle = 'rgba(5, 5, 5, 0.3)'; // Trail effect
        ctx.fillRect(0, 0, canvas.width, canvas.height);

        for (let i = particles.length - 1; i >= 0; i--) {
            const p = particles[i];
            p.x += p.vx;
            p.y += p.vy;
            p.vy += p.gravity;
            p.life--;

            if (p.life <= 0) {
                particles.splice(i, 1);
                continue;
            }

            const alpha = activeParams.fade ? (p.life / p.maxLife) : 1;
            ctx.globalAlpha = Math.max(0, alpha);
            ctx.fillStyle = p.color;
            ctx.strokeStyle = p.color;
            ctx.lineWidth = 2;

            ctx.beginPath();
            if (p.shape === 'circle') {
                ctx.arc(p.x, p.y, p.size, 0, Math.PI * 2);
                ctx.fill();
            } else if (p.shape === 'square') {
                // simple rotation for square
                ctx.save();
                ctx.translate(p.x, p.y);
                ctx.rotate(p.life * 0.1);
                ctx.fillRect(-p.size/2, -p.size/2, p.size, p.size);
                ctx.restore();
            } else if (p.shape === 'line') {
                ctx.moveTo(p.x, p.y);
                ctx.lineTo(p.x - p.vx * 2, p.y - p.vy * 2);
                ctx.stroke();
            } else if (p.shape === 'ring') {
                ctx.arc(p.x, p.y, p.size, 0, Math.PI * 2);
                ctx.stroke();
            } else if (p.shape === 'star') {
                ctx.save();
                ctx.translate(p.x, p.y);
                ctx.rotate(p.life * 0.05);
                for(let j=0; j<5; j++) {
                    ctx.lineTo(0, -p.size);
                    ctx.rotate(Math.PI / 5);
                    ctx.lineTo(0, -p.size * 0.4);
                    ctx.rotate(Math.PI / 5);
                }
                ctx.closePath();
                ctx.fill();
                ctx.restore();
            } else if (p.shape === 'heart') {
                ctx.save();
                ctx.translate(p.x, p.y);
                const s = p.size * 0.05;
                ctx.scale(s, s);
                ctx.moveTo(0, -5);
                ctx.bezierCurveTo(0, -15, -15, -25, -25, -15);
                ctx.bezierCurveTo(-40, 0, -10, 25, 0, 40);
                ctx.bezierCurveTo(10, 25, 40, 0, 25, -15);
                ctx.bezierCurveTo(15, -25, 0, -15, 0, -5);
                ctx.fill();
                ctx.restore();
            }
            ctx.globalAlpha = 1;
        }

        requestAnimationFrame(render);
    }

    buildUI('explosion');
    render();

    btnExport.addEventListener('click', () => {
        const area = document.getElementById('codeExportArea');
        area.style.display = 'block';

        const code = `
// Универсальный генератор частиц для Playables (без зависимостей)
class ParticleSystem {
    constructor(canvasId) {
