        this.params = ${JSON.stringify(activeParams, null, 4)};
    }

    emit(x, y) {
        let baseAngle = -Math.PI / 2;
        if (this.params.shape === 'line' && this.params.spread < 45) baseAngle = Math.PI / 2;

        for (let i = 0; i < this.params.count; i++) {
            const spreadRad = (this.params.spread * Math.PI) / 180;
            const angle = baseAngle + (Math.random() - 0.5) * spreadRad;
            const speed = this.params.speed * (0.5 + Math.random() * 0.5);

            this.particles.push({
                x: x, y: y,
