            this.ctx.globalAlpha = this.params.fade ? Math.max(0, p.life / p.maxLife) : 1;
            this.ctx.fillStyle = p.color;
            this.ctx.strokeStyle = p.color;
            this.ctx.lineWidth = 2;

            this.ctx.beginPath();
            if (this.params.shape === 'circle') {
                this.ctx.arc(p.x, p.y, p.size, 0, Math.PI * 2);
                this.ctx.fill();
            } else if (this.params.shape === 'square') {
                this.ctx.save();
                this.ctx.translate(p.x, p.y);
                this.ctx.rotate(p.life * 0.1);
                this.ctx.fillRect(-p.size/2, -p.size/2, p.size, p.size);
                this.ctx.restore();
            } else if (this.params.shape === 'line') {
                this.ctx.moveTo(p.x, p.y);
                this.ctx.lineTo(p.x - p.vx * 2, p.y - p.vy * 2);
                this.ctx.stroke();
            } else if (this.params.shape === 'ring') {
                this.ctx.arc(p.x, p.y, p.size, 0, Math.PI * 2);
                this.ctx.stroke();
            } else if (this.params.shape === 'star') {
                this.ctx.save();
                this.ctx.translate(p.x, p.y);
                this.ctx.rotate(p.life * 0.05);
                for(let j=0; j<5; j++) {
                    this.ctx.lineTo(0, -p.size);
                    this.ctx.rotate(Math.PI / 5);
                    this.ctx.lineTo(0, -p.size * 0.4);
                    this.ctx.rotate(Math.PI / 5);
                }
                this.ctx.closePath();
                this.ctx.fill();
                this.ctx.restore();
            } else if (this.params.shape === 'heart') {
                this.ctx.save();
                this.ctx.translate(p.x, p.y);
                const s = p.size * 0.05;
                this.ctx.scale(s, s);
                this.ctx.moveTo(0, -5);
                this.ctx.bezierCurveTo(0, -15, -15, -25, -25, -15);
                this.ctx.bezierCurveTo(-40, 0, -10, 25, 0, 40);
                this.ctx.bezierCurveTo(10, 25, 40, 0, 25, -15);
