uniform float u_time;
uniform float u_speed;
uniform float u_frequency;
uniform float u_amplitude;
varying vec2 vUv;

// Имитация базовой текстуры для предпросмотра
vec3 getBase(vec2 uv) {
    float grid = step(0.9, sin(uv.x * 50.0)) + step(0.9, sin(uv.y * 50.0));
    return mix(vec3(0.1, 0.2, 0.3), vec3(0.2, 0.8, 0.4), grid);
}

void main() {
    vec2 uv = vUv;
    uv.y += sin(uv.x * u_frequency + u_time * u_speed) * u_amplitude;
    uv.x += cos(uv.y * u_frequency + u_time * u_speed) * u_amplitude;
    gl_FragColor = vec4(getBase(uv), 1.0);
}
