uniform float u_time;
uniform float u_intensity;
uniform float u_speed;
varying vec2 vUv;

float rand(vec2 co){
    return fract(sin(dot(co.xy ,vec2(12.9898,78.233))) * 43758.5453);
}

vec3 getBase(vec2 uv) {
    float grid = step(0.9, sin(uv.x * 50.0)) + step(0.9, sin(uv.y * 50.0));
    return mix(vec3(0.1, 0.2, 0.3), vec3(0.2, 0.8, 0.4), grid);
}

void main() {
    vec2 uv = vUv;
    float time = floor(u_time * u_speed);
    float splitAmnt = 0.0;
    if(rand(vec2(time, 1.0)) > 0.8) {
        splitAmnt = (rand(vec2(time, 2.0)) - 0.5) * u_intensity;
    }

    float scanline = sin(uv.y * 800.0) * 0.04;
    vec2 uvR = uv + vec2(splitAmnt, 0.0);
    vec2 uvG = uv;
    vec2 uvB = uv - vec2(splitAmnt, 0.0);

    vec3 col = vec3(
        getBase(uvR).r,
        getBase(uvG).g,
        getBase(uvB).b
    ) - scanline;

    gl_FragColor = vec4(col, 1.0);
}
