uniform float u_time;
uniform float u_distortion;
uniform float u_scanlines;
uniform float u_vignette;
varying vec2 vUv;

vec3 getBase(vec2 uv) {
    float text = step(0.8, fract(sin(dot(uv*floor(u_time*5.0) ,vec2(12.9898,78.233))) * 43758.5453));
    return mix(vec3(0.0, 0.2, 0.1), vec3(0.0, 1.0, 0.3), text);
}

void main() {
    vec2 uv = vUv;
    vec2 cc = uv - 0.5;
    float dist = dot(cc, cc) * u_distortion;
    uv = uv + cc * (1.0 + dist) * dist;

    if (uv.x < 0.0 || uv.x > 1.0 || uv.y < 0.0 || uv.y > 1.0) {
        gl_FragColor = vec4(0.0, 0.0, 0.0, 1.0);
        return;
    }

    vec3 color = getBase(uv);
    float scanline = sin(uv.y * 800.0) * 0.1 * u_scanlines;
    color -= scanline;

    float vig = 1.0 - smoothstep(0.3, 0.8, length(vUv - 0.5)) * u_vignette;
    color *= vig;

    gl_FragColor = vec4(color, 1.0);
}
