        uniforms: {
          u_speed: { type: 'f', value: 1.0, min: 0.1, max: 3.0, label: 'Скорость течения' },
          u_color: { type: 'c', value: '#ff3300', label: 'Цвет лавы' },
          u_color2: { type: 'c', value: '#ffff00', label: 'Цвет ядра' }
        },
        fragmentShader: `
uniform float u_time;
uniform float u_speed;
uniform vec3 u_color;
uniform vec3 u_color2;
varying vec2 vUv;

// Fake metaballs / noise
float noise(vec2 p) {
    return sin(p.x * 3.0 + u_time * u_speed) * cos(p.y * 3.0 + u_time * u_speed * 0.5) * 0.5 + 0.5;
}

void main() {
    vec2 uv = vUv * 2.0 - 1.0;
    uv.x *= 1.5; // aspect ratio approximation

    float v = 0.0;

    // Add multiple blobs
    for(int i = 1; i <= 5; i++) {
        float fi = float(i);
        vec2 pos = vec2(
            sin(u_time * u_speed * 0.3 * fi),
            cos(u_time * u_speed * 0.4 * fi)
        );
        float d = length(uv - pos);
        v += 0.1 / d; // metaball formula
    }

    // Threshold
    float iso = smoothstep(0.8, 1.2, v);

    // Core heat
    float core = smoothstep(1.2, 2.0, v);

    vec3 col = mix(vec3(0.05, 0.0, 0.0), u_color, iso);
    col = mix(col, u_color2, core);

    gl_FragColor = vec4(col, 1.0);
}
        `
      }
    };

    // Scene Setup
    const container = document.getElementById('canvasWrapper');
    const renderer = new THREE.WebGLRenderer({ antialias: true, alpha: true });
    renderer.setPixelRatio(window.devicePixelRatio);
    renderer.setSize(container.clientWidth, container.clientHeight);
    container.appendChild(renderer.domElement);

    const camera = new THREE.OrthographicCamera(-1, 1, 1, -1, 0, 1);
    const scene = new THREE.Scene();

    const geometry = new THREE.PlaneGeometry(2, 2);
    let material, mesh;
    let uniforms = { u_time: { value: 0 } };

    const presetSelect = document.getElementById('presetSelect');
    const uniformsContainer = document.getElementById('uniformsContainer');
    const btnExport = document.getElementById('btnExport');
    const codeExportArea = document.getElementById('codeExportArea');
    const codeTextarea = document.getElementById('codeTextarea');

    function buildUI(presetKey) {
      const preset = presets[presetKey];
      uniformsContainer.innerHTML = '';

      uniforms = { u_time: { value: 0 } };

      for (const [key, data] of Object.entries(preset.uniforms)) {
        const group = document.createElement('div');
        group.className = 'form-group';

        const label = document.createElement('label');
        label.className = 'form-label';

        if (data.type === 'c') {
          uniforms[key] = { value: new THREE.Color(data.value) };
          label.innerHTML = `${data.label}: <span id="val_${key}">${data.value}</span>`;

          const input = document.createElement('input');
          input.type = 'color';
          input.value = data.value;
          input.style.width = '100%';
          input.style.height = '40px';
          input.style.border = 'none';
          input.style.padding = '0';
          input.style.cursor = 'pointer';

          input.addEventListener('input', (e) => {
            document.getElementById(`val_${key}`).innerText = e.target.value;
            uniforms[key].value.set(e.target.value);
          });

          group.appendChild(label);
          group.appendChild(input);
        } else {
          uniforms[key] = { value: data.value };
          label.innerHTML = `${data.label}: <span id="val_${key}">${data.value}</span>`;

          const input = document.createElement('input');
          input.type = 'range';
          input.min = data.min;
          input.max = data.max;
          input.step = data.step || 0.01;
          input.value = data.value;

          input.addEventListener('input', (e) => {
            const val = parseFloat(e.target.value);
            document.getElementById(`val_${key}`).innerText = val.toFixed(2);
            uniforms[key].value = val;
          });

          group.appendChild(label);
          group.appendChild(input);
        }

        uniformsContainer.appendChild(group);
      }

      updateMaterial(preset.fragmentShader);
    }

    function updateMaterial(fragmentShader) {
      if (mesh) scene.remove(mesh);

      material = new THREE.ShaderMaterial({
        uniforms: uniforms,
        vertexShader: `
          varying vec2 vUv;
          void main() {
            vUv = uv;
            gl_Position = vec4(position, 1.0);
          }
        `,
        fragmentShader: fragmentShader
      });

      mesh = new THREE.Mesh(geometry, material);
      scene.add(mesh);
    }

    presetSelect.addEventListener('change', (e) => {
      buildUI(e.target.value);
      codeExportArea.style.display = 'none';
    });

    btnExport.addEventListener('click', () => {
      codeExportArea.style.display = 'block';
      const presetKey = presetSelect.value;
      codeTextarea.value = presets[presetKey].fragmentShader.trim();
    });

    document.getElementById('btnSavePreset').addEventListener('click', () => {
      const pKey = presetSelect.value;
      const valuesToSave = {};
      Object.keys(presets[pKey].uniforms).forEach(k => {
        valuesToSave[k] = presets[pKey].uniforms[k].value;
      });
      localStorage.setItem('shader_preset_' + pKey, JSON.stringify(valuesToSave));
      alert('Настройки для ' + pKey + ' сохранены!');
    });

    document.getElementById('btnLoadPreset').addEventListener('click', () => {
      const pKey = presetSelect.value;
      const saved = localStorage.getItem('shader_preset_' + pKey);
      if (saved) {
        const values = JSON.parse(saved);
        Object.keys(values).forEach(k => {
          if (presets[pKey].uniforms[k]) {
            presets[pKey].uniforms[k].value = values[k];
          }
        });
        buildUI(pKey); // Rebuild UI to update sliders
        alert('Настройки для ' + pKey + ' загружены!');
      } else {
        alert('Нет сохраненных настроек для этого эффекта.');
      }
    });

    // Init
    buildUI('wave');

    // Render loop
    const clock = new THREE.Clock();
    function animate() {
      requestAnimationFrame(animate);
      uniforms.u_time.value = clock.getElapsedTime();
      renderer.render(scene, camera);
    }
    animate();

    window.addEventListener('resize', () => {
      renderer.setSize(container.clientWidth, container.clientHeight);
    });
